import sys,numpy as np
sys.path.insert(0,'work')
from score import compose
from inspect_mix import read,db
from synthesis import freq
from tracker import SPEED
s=compose(); mat=s.compile(); measure={}
for ch,stem in zip((5,6,7),('bass','lead','answer')):
 sr,x=read(f'work/stem_{stem}.wav'); h=x.mean(axis=1); bad=[]; pan=[]; errs=[]
 for e in s.lanes[ch]:
  length=min(4800,e.dur*800-1500); i=e.t*800+(1280 if ch==5 else 960)
  if length<800: continue
  y=h[i:i+length]; w=np.hanning(len(y)); z=np.fft.rfft(y*w,n=16384); fq=np.fft.rfftfreq(16384,1/sr); fp=freq(e.note)
  a=np.abs(z);
  if e.tie:
   pad=3840; y=h[e.t*800+pad:e.t*800+4800]; z=np.fft.rfft(y*np.hanning(len(y)),n=16384); a=np.abs(z)
  inds=np.arange(max(1,np.searchsorted(fq,fp*.46)),np.searchsorted(fq,fp*2.2)); p=inds[np.argmax(a[inds])];
  p1,p2,p3=np.log(a[p-1:p+2].clip(1e-8)); delta=.5*(p1-p3)/(p1 -2*p2 +p3+1e-10); f=(p+delta)*sr/16384
  err=1200*np.log2(f/fp); errs.append(err)
  if abs(err)>45 or np.max(np.abs(y))<.001:
   bad.append((e.t//96, round(e.t%96/6,2), e.note,e.flags, round(float(err),1),round(float(db(np.std(y))),1)))
 print(stem,'notes checked',len(errs),'pitch err centiles',np.round(np.quantile(errs,[0,.05,.25,.5,.75,.95,1]),1), 'issues',len(bad),bad[:30])
print('arps, pattern 6:')
for row in range(24*16,25*16):
 print(row%16,mat[row,10:12,:].tolist())
